def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == 0:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    result = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    # Enclosed regions are colored according to the interior square size:
    # 3x3 -> 8, 5x5 -> 4, 7x7 -> 3.
    color_for_size = {3: 8, 5: 4, 7: 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and not outside[nr][nc] and not seen[nr][nc]):
                        seen[nr][nc] = True
                        q.append((nr, nc))
            height = max(rr for rr, _ in cells) - min(rr for rr, _ in cells) + 1
            width = max(cc for _, cc in cells) - min(cc for _, cc in cells) + 1
            color = color_for_size.get(max(height, width), 8)
            for rr, cc in cells:
                result[rr][cc] = color
    return result


